CREATE POLICY "Enrolled students can view directly attached audio playlists" ON public.audio_playlists FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_content_links pcl JOIN public.course_enrollments ce ON ce.program_slug = pcl.program_slug WHERE pcl.content_type = 'audio' AND pcl.content_id = audio_playlists.id AND ce.user_id = auth.uid() AND ce.status = 'active'));
CREATE POLICY "Enrolled students can view directly attached audio playlist items" ON public.audio_playlist_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_content_links pcl JOIN public.course_enrollments ce ON ce.program_slug = pcl.program_slug WHERE pcl.content_type = 'audio' AND pcl.content_id = audio_playlist_items.playlist_id AND ce.user_id = auth.uid() AND ce.status = 'active'));
CREATE POLICY "Enrolled students can view directly attached audio content" ON public.audio_content FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.audio_playlist_items api JOIN public.program_content_links pcl ON pcl.content_id = api.playlist_id AND pcl.content_type = 'audio' JOIN public.course_enrollments ce ON ce.program_slug = pcl.program_slug WHERE api.audio_id = audio_content.id AND ce.user_id = auth.uid() AND ce.status = 'active'));